def assert_role_media_now(testCase, dut, port, role):
    """Assert the media of a PLUGGABLE role NOW — after the operator has (re)fitted the module.

    Module-level on purpose: the frame's lint reads every `self.testSet.<name>` as a device
    handle that init() must bind. Records the verdict on `testCase` and returns True/False,
    because by this point a wrong module is a test-relevant observation the operator can
    correct — unlike at init(), where a missing link is a bench problem.
    """
    import ck_media
    status = dut.cmd('show interface %s status' % port.name)
    ok, why = ck_media.assert_role_media(status, port.name, role)
    if ok:
        testCase.passed('module on %s matches the %r role: %s' % (port.name, role, why))
    else:
        testCase.failed('module on %s does NOT match the %r role: %s' % (port.name, role, why))
    return ok


class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']
    def _ck_discover(self, dut, unit=None):
        """Every data link on the DUT, classified by asking the DUT what is fitted in each port.

        `dut` is the switch handle commands go to; `unit` is what owns the ports — the STACK
        when the DUT is in one (its members' [portlink]s all count), else `dut` itself.

        Fixed frame — do not edit or delete. Nothing here is pre-declared (Terrence, 2026-09-21:
        "the information shouldn't require pre-loading variables to know it"). The cables come
        from the bench's own [portlink] section through `get_all_port_links()`; the testbox is
        the far end that is a TestBox; a member of the DUT's own stack is never a partner; and
        the MEDIA of each DUT-side port is read from `show interface <port> status` (its Type
        column) and `show system pluggable` (which cages hold a module). An EMPTY cage has no
        media and is no role — nothing is in it.
        Returns {bucket: [(near_port, far_port, far_device), ...]} for the buckets
        tb / copper (fixed twisted pair) / cusfp (twisted pair in a cage) / fibre / absent / unknown.
        """
        import ck_media
        unit = unit if unit is not None else dut
        members = set(unit.all_members()) if hasattr(unit, 'all_members') else set()
        in_cage = ck_media.pluggable_ports(dut.cmd('show system pluggable'))
        found = {'tb': [], 'copper': [], 'cusfp': [], 'fibre': [], 'absent': [], 'unknown': []}
        for far, pairs in unit.get_all_port_links().items():
            if far in members:
                continue                       # stackport / member cabling is not a data path
            for near, far_port in pairs:
                if isinstance(far, ATTestBox.TestBox):
                    found['tb'].append((near, far_port, far))
                    continue
                if not near.name.startswith('port'):
                    continue                   # an eth0 management link is not a data path
                status = dut.cmd('show interface %s status' % near.name)
                kind = ck_media.classify(ck_media.media_type(status, near.name))
                if kind == ck_media.TWISTED_PAIR:
                    bucket = 'cusfp' if ck_media.is_pluggable(near.name, in_cage) else 'copper'
                elif kind == ck_media.FIBRE:
                    bucket = 'fibre'
                elif kind == ck_media.ABSENT:
                    bucket = 'absent'
                else:
                    bucket = 'unknown'
                found[bucket].append((near, far_port, far))
        self.log('topology discovered on %s: %s' % (dut.name, '; '.join(
            '%s=%s' % (k, ','.join('%s<->%s.%s' % (n.name, getattr(f, 'name', 'tb'), p.name)
                                    for n, p, f in v))
            for k, v in found.items() if v) or 'NO data links declared'))
        return found

    def _ck_bind_link(self, setup, dut, role, optional=False):
        """Take ONE discovered link for `role` and bind it: (near_port, far_port, far_device).

        Fixed frame — do not edit or delete. `role` is what the TEST needs — 'tb', 'copper',
        'fibre', 'cusfp' — and the link is whichever discovered cable carries that media, so
        the same script binds on any bench cabled for it while the bench declares nothing
        beyond its [portlink]s. A link is never handed out twice; a copper role takes a copper
        SFP only when no fixed twisted-pair link is left; a partner switch is initialised once
        however many links go to it. A REQUIRED role with no link aborts the suite — "this
        bench cannot host this test" is a bench problem, not a test result. An OPTIONAL
        (pluggable) role returns (None, None, None) and the cases needing it report UNSUPPORTED.
        """
        import ck_media
        buckets = {'tb': ('tb',), 'copper': ('copper', 'cusfp'),
                   'cusfp': ('cusfp',), 'fibre': ('fibre',)}[role]
        for bucket in buckets:
            if not self._ck_topo.get(bucket):
                continue
            near, far_port, far = self._ck_topo[bucket].pop(0)
            if isinstance(far, ATTestBox.TestBox):
                # The testbox end of a data link: any fitted media serves a capture/inject
                # path, but an EMPTY cage on the DUT side is a bench problem — say so now.
                status = dut.cmd('show interface %s status' % near.name)
                ok, why = ck_media.assert_role_media(status, near.name, 'tb')
                if not ok:
                    raise RuntimeError(why)
            else:
                if far.name not in self._ck_far:
                    self._ck_far[far.name] = (setup.init_stk(far.name) if hasattr(far, 'all_members')
                                              else setup.init_swi(far.name))
                far = self._ck_far[far.name]
            self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
                role, dut.name, near.name, getattr(far, 'name', 'tb'), far_port.name, bucket))
            return near, far_port, far
        have = ', '.join('%d %s' % (len(v), k) for k, v in self._ck_topo.items() if v) or 'none'
        why = ("BENCH PROBLEM, not a product defect: no unused %s link on %s (data links "
               "discovered: %s). Cable a %s partner port to the DUT and declare it under "
               "[portlink]." % (role, dut.name, have, role))
        if optional:
            self.log(why + ' This role is OPTIONAL here: the cases needing it report UNSUPPORTED.')
            return None, None, None
        raise RuntimeError(why)


    def init(self, setup):
        # Topology is DISCOVERED through the framework at run time, never declared to this
        # script: the DUT is the framework's `swi_a` slot (its stack, when it is in one), the
        # partners are whatever the bench's [portlink]s cable to it, and which link is copper
        # / fibre / copper-SFP is read from the DUT itself. So the script names no port and no
        # partner, binds correctly on any bench cabled for it, and fails loudly on one that is
        # not. (`swi_a`/`stk_a`: 297/192 corpus lookups; a role-named key appears 0 times.)
        tb = setup.init_tb()
        dut = setup.init_swi('swi_a')
        # ART's own shape (103 of 239 suites bind BOTH the stack and the swi_a switch):
        # the STACK owns the ports [portlink] declares per member and is what discovery walks;
        # COMMANDS go to the swi_a member handle, which has cmd()/mode() — the framework's Stack
        # class defines neither, and every VCStack member serves the stack-wide CLI. (2026-09-21
        # to 2026-09-23 the frame rebound `dut` to the Stack, so every command died on a
        # stacked DUT; Terrence: "Copy what they do, because it works.")
        _stk = dut.get_stack()
        dut_stack = setup.init_stk(_stk.name) if _stk is not None else None
        self.tb = tb
        self.dut = dut
        self.dut_stack = dut_stack
        self._ck_far = {}
        self._ck_topo = self._ck_discover(dut, dut_stack)
        # The COPPER-SFP link (a 1000BASE-T module in a cage), OPTIONAL: taken first so the
        # copper role below cannot consume it. A bench without a fitted copper SFP leaves the
        # handles None and `self.cusfp_supported` False; the cases that need it check the
        # flag and report UNSUPPORTED instead of failing. Far port: `cusfp_peer.portCuSfp`.
        (dut.portCuSfp, cusfp_port, cusfp_peer) = self._ck_bind_link(
            setup, dut, 'cusfp', optional=True)
        self.cusfp_supported = cusfp_peer is not None
        if self.cusfp_supported:
            cusfp_peer.portCuSfp = cusfp_port
        self.cusfp_peer = cusfp_peer
        # The FIBRE link (a fitted fibre module), OPTIONAL in the same shape; the flag is
        # `self.fibre_supported`, the far port `fibre_peer.portFibre`. Role-specific far names
        # on purpose: two pluggable links often land on the SAME partner switch, and a shared
        # `.portDut` there would be overwritten by the next binding.
        (dut.portFibre, fibre_port, fibre_peer) = self._ck_bind_link(
            setup, dut, 'fibre', optional=True)
        self.fibre_supported = fibre_peer is not None
        if self.fibre_supported:
            fibre_peer.portFibre = fibre_port
        self.fibre_peer = fibre_peer
        # The NEIGHBOUR switch on a fixed twisted-pair link, REQUIRED: a partner to negotiate
        # against, a polarity to force, a neighbour table to read. Named `peer`, never `dut`:
        # in ART `dut` is the DUT's own stack handle, and a partner called `dut` made every
        # model read `dut.portA` as the DUT's port (T44297, 2026-09-07).
        (dut.portPeer, peer_port, peer) = self._ck_bind_link(setup, dut, 'copper')
        peer.portDut = peer_port
        self.peer = peer
        # NOT BOUND: dutA.
        # A test binds the DUT plus the partners at the far end of the links it needs. These
        # names were only ever inferred from the vocabulary of the selected fragments, which is
        # not evidence the test needs them — and every unused binding becomes a topology demand
        # a bench has to satisfy for nothing. Needing another partner means the case needs
        # another link role, not a device guessed here.

    def configure(self):
        tb = self.tb
        dut = self.dut
        peer = self.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.fibre_peer          # None when self.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.cusfp_peer          # None when self.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # setup: From the frame's discovered links, resolve the copper test port (a fitted copper pluggable cabled to a partner port), the fibre test port (a fitted fibre pluggable cabled to a partner port), and at least one other linked DUT port (the monitored port). Precondition: the copper and fibre pluggables are fitted and cabled before the run; if either media has no discovered link, log that media's sweep as UNSUPPORTED. On each test port and its partner port, apply `no speed`, `duplex auto` and `no shutdown`. Save a backup copy of the DUT's startup configuration so it can be restored at teardown.
        # setup: Teardown. On the DUT copper and fibre test ports and on their partner ports apply `no speed` and `duplex auto`. Restore the DUT startup configuration from the backup taken in step 1.
        # legacy 5703_Speed_Duplex_Polarity/test-5000.1001.py lines 9-31 (adapted: pluggable/link resolution)
        self.startupBackup = 'flash:/ck_t33235_startup_backup.cfg'
        self.startupBackupTaken = False
        testPorts = []
        if self.cusfp_supported and cusfp_peer is not None and portCuSfp is not None:
            testPorts.append((dut, portCuSfp))
            testPorts.append((cusfp_peer, cusfp_peer.portCuSfp))
            self.log('INFO: copper test port {} on {} <-> partner port {} on {}'.format(
                portCuSfp.name, dut, cusfp_peer.portCuSfp.name, cusfp_peer))
        else:
            self.log('INFO: no copper pluggable link discovered on {}; copper speed sweep is UNSUPPORTED'.format(dut))
        if self.fibre_supported and fibre_peer is not None and portFibre is not None:
            testPorts.append((dut, portFibre))
            testPorts.append((fibre_peer, fibre_peer.portFibre))
            self.log('INFO: fibre test port {} on {} <-> partner port {} on {}'.format(
                portFibre.name, dut, fibre_peer.portFibre.name, fibre_peer))
        else:
            self.log('INFO: no fibre pluggable link discovered on {}; fibre speed sweep is UNSUPPORTED'.format(dut))
        self.log('INFO: monitored port {} on {} <-> port {} on {}'.format(
            portPeer.name, dut, portDut.name, peer))

        # legacy 5000_mdi_mdix/library_5000.py lines 88-119 — reset each test/partner port to defaults
        for dev, port in testPorts:
            configureDefaultPort(self, dev, port)
            dev.mode(')#')
            dev.cmd('interface {}'.format(port.name))
            dev.cmd('no speed')
            dev.cmd('duplex auto')
            dev.cmd('no shutdown')
            dev.mode('#')

        # Back up the DUT startup configuration so tear_down() can restore it
        dut.mode('#')
        dut.cmd('delete force {}'.format(self.startupBackup))
        output = dut.cmd('copy startup-config {}'.format(self.startupBackup))
        if '(y/n)' in output:
            output = dut.cmd('y')
        self.log('OBSERVED: startup-config backup output: {}'.format(output))
        errorTokens = ('Error', 'Invalid', 'No such file', 'Cannot', 'failed')
        self.startupBackupTaken = not any(token in output for token in errorTokens)
        if self.startupBackupTaken:
            self.log('INFO: DUT startup-config backed up to {}'.format(self.startupBackup))
        else:
            self.log('INFO: DUT startup-config backup to {} did not complete; restore will be skipped'.format(
                self.startupBackup))
        dut.mode('#')

    def tear_down(self):
        tb = self.tb
        dut = self.dut
        peer = self.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.fibre_peer          # None when self.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.cusfp_peer          # None when self.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        testPorts = []
        if self.cusfp_supported and cusfp_peer is not None and portCuSfp is not None:
            testPorts.append((dut, portCuSfp))
            testPorts.append((cusfp_peer, cusfp_peer.portCuSfp))
        if self.fibre_supported and fibre_peer is not None and portFibre is not None:
            testPorts.append((dut, portFibre))
            testPorts.append((fibre_peer, fibre_peer.portFibre))

        for dev, port in testPorts:
            self.log('LOG {}: restoring port {} to no speed / duplex auto'.format(dev, port.name))
            dev.mode(')#')
            dev.cmd('interface {}'.format(port.name))
            dev.cmd('no speed')
            dev.cmd('duplex auto')
            dev.mode('#')

        # Restore the DUT startup configuration from the backup taken in configure()
        dut.mode('#')
        if getattr(self, 'startupBackupTaken', False):
            output = dut.cmd('copy {} startup-config'.format(self.startupBackup))
            if '(y/n)' in output:
                output = dut.cmd('y')
            self.log('OBSERVED: startup-config restore output: {}'.format(output))
            dut.cmd('delete force {}'.format(self.startupBackup))
        else:
            self.log('INFO: no startup-config backup was taken; skipping restore on {}'.format(dut))
        dut.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = 'On the copper test link: Poll `show interface <test port> status` for up to 30 s, then read `show interface <test port>` and `show interface <partner port> status` on the partner.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33235, 9001.33235.1'
    testCaseMethod = 'On the copper test link: Poll `show interface <test port> status` for up to 30 s, then read `show interface <test port>` and `show interface <partner port> status` on the partner.\n'
    testCaseMethod += 'Verify: On the row whose first token is the test port, the status column reads `connected`, the duplex column is `a-` prefixed (e.g. `a-full`) and the speed column is `a-` prefixed (e.g. `a-1000`). `show interface <test port>` has a current line with a concrete `current duplex` and `current speed` value, not the literal `auto`. The partner row is also `connected` with `a-` prefixed values. Record the negotiated speed, duplex and `a-` prefixed tokens as the baseline.\n'

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # The baseline presumes both ends of the copper link are at their auto-negotiate defaults.
        configureDefaultPort(self, peer, portDut)
        configureDefaultPort(self, dut, portPeer)
        peer.mode('#')
        dut.mode('#')

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 241-270
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        self.log('STEP 2: On the copper test link: Poll `show interface <test port> status` for up to 30 s, then read `show interface <test port>` and `show interface <partner port> status` on the partner.')

        def find_row(text, name):
            return next((line for line in text.splitlines() if line.split()[:1] == [name]), None)

        def split_auto_tokens(row):
            tokens = row.split()
            a_tokens = [tok for tok in tokens if tok.startswith('a-')]
            duplex_tok = next((tok for tok in a_tokens if tok[2:] in ('full', 'half')), None)
            speed_tok = next((tok for tok in a_tokens if tok != duplex_tok and tok[2:] != ''), None)
            return 'connected' in tokens, duplex_tok, speed_tok

        test_name = portPeer.name
        partner_name = portDut.name

        dut.mode('#')
        status_out = ''
        test_row = None
        deadline = time.time() + 30
        while True:
            status_out = dut.cmd('show interface {} status'.format(test_name), log=False)
            test_row = find_row(status_out, test_name)
            if test_row is not None and 'connected' in test_row.split():
                break
            if time.time() >= deadline:
                break
            time.sleep(2)

        intf_out = dut.cmd('show interface {}'.format(test_name))
        peer.mode('#')
        partner_out = peer.cmd('show interface {} status'.format(partner_name))
        output = '{}\n{}\n{}'.format(status_out, intf_out, partner_out)
        self.log('OBSERVED: {}'.format(output))

        if test_row is None:
            self.failed('test port {} missing from show interface status output on the DUT'.format(test_name))
            return

        connected, duplex_tok, speed_tok = split_auto_tokens(test_row)
        if connected:
            self.passed('{} status row reads connected within 30 s: {}'.format(test_name, test_row.strip()))
        else:
            self.failed('{} status row not connected after 30 s: {}'.format(test_name, test_row.strip()))
            return

        if duplex_tok is not None:
            self.passed('{} duplex column is auto-negotiated: {}'.format(test_name, duplex_tok))
        else:
            self.failed('{} duplex column has no a- prefixed full/half token: {}'.format(test_name, test_row.strip()))

        if speed_tok is not None:
            self.passed('{} speed column is auto-negotiated: {}'.format(test_name, speed_tok))
        else:
            self.failed('{} speed column has no a- prefixed speed token: {}'.format(test_name, test_row.strip()))

        cur_duplex = None
        cur_speed = None
        for line in intf_out.splitlines():
            if 'current duplex' in line and 'current speed' in line:
                for part in line.strip().split(','):
                    words = part.strip().split()
                    if len(words) >= 3 and words[0] == 'current' and words[1] == 'duplex':
                        cur_duplex = words[2]
                    elif len(words) >= 3 and words[0] == 'current' and words[1] == 'speed':
                        cur_speed = words[2]
                break

        if cur_duplex is None or cur_speed is None:
            self.failed('show interface {} has no current duplex/current speed line'.format(test_name))
        elif cur_duplex == 'auto' or cur_speed == 'auto':
            self.failed('show interface {} current line not concrete: current duplex {}, current speed {}'.format(
                test_name, cur_duplex, cur_speed))
        else:
            self.passed('show interface {} reports concrete current duplex {}, current speed {}'.format(
                test_name, cur_duplex, cur_speed))

        partner_row = find_row(partner_out, partner_name)
        if partner_row is None:
            self.failed('partner port {} missing from show interface status output on the partner'.format(partner_name))
            return

        p_connected, p_duplex_tok, p_speed_tok = split_auto_tokens(partner_row)
        if p_connected and p_duplex_tok is not None and p_speed_tok is not None:
            self.passed('partner {} row is connected with {} {}'.format(partner_name, p_duplex_tok, p_speed_tok))
        else:
            self.failed('partner {} row not connected with a- prefixed duplex/speed: {}'.format(
                partner_name, partner_row.strip()))

        baseline = {
            'test_port': test_name,
            'partner_port': partner_name,
            'current_duplex': cur_duplex,
            'current_speed': cur_speed,
            'status_duplex': duplex_tok,
            'status_speed': speed_tok,
            'partner_duplex': p_duplex_tok,
            'partner_speed': p_speed_tok,
        }
        self.log('INFO: copper baseline recorded: {}'.format(baseline))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # configure() only applied the defaults and main() changed nothing; re-assert the
        # defaults so the next case starts from auto speed/duplex/polarity on both ends.
        configureDefaultPort(self, peer, portDut)
        configureDefaultPort(self, dut, portPeer)
        peer.mode('#')
        dut.mode('#')


class TestCase_2(ATTestCase.TestCase):
    testCaseDesc = 'On the copper test link, attempt `10` whatever the port type. On the partner port apply `speed 10` and `duplex full`, then on the DUT copper test port apply `speed 10` and `duplex full`. Poll `show interface <copper test port> status` for up to 30 s, then read `show interface <copper test port>` and `show running-config interface <copper test port>`.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33235, 9001.33235.2'
    testCaseMethod = 'On the copper test link, attempt `10` whatever the port type. On the partner port apply `speed 10` and `duplex full`, then on the DUT copper test port apply `speed 10` and `duplex full`. Poll `show interface <copper test port> status` for up to 30 s, then read `show interface <copper test port>` and `show running-config interface <copper test port>`.\n'
    testCaseMethod += "Verify: If the legal-values table lists `10` for the copper port's type, the DUT accepts the command, the test port row reads `connected` with bare `10` and bare `full` (no `a-` prefix), and the current line reads `current duplex full, current speed 10`. If the legal-values table does not list `10` for the port's type, the DUT rejects the command with an error indication, running-config gains no `speed 10` line, and the port's previous speed and link state are unchanged. If the partner rejects the command, log it; judge only the DUT's accept or reject, and do not assert link-up. The console stays at the prompt with no boot output.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # Both ends of the copper test link start from default speed/duplex/polarity (auto).
        configureDefaultPort(self, peer, portDut)
        configureDefaultPort(self, dut, portPeer)
        peer.mode('#')
        dut.mode('#')

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 61-85
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        self.log('STEP 3: On the copper test link, attempt `10` whatever the port type. On the partner port apply `speed 10` and `duplex full`, then on the DUT copper test port apply `speed 10` and `duplex full`. Poll `show interface <copper test port> status` for up to 30 s, then read `show interface <copper test port>` and `show running-config interface <copper test port>`.')
        name = portPeer.name
        err_tokens = ('Invalid', 'invalid', 'failed', 'Cannot', 'cannot', 'not supported',
                      'Error', 'error', '% ')
        boot_tokens = ('Bootloader', 'Booting', 'login:', 'Restarting system')

        def port_row(text):
            for line in text.splitlines():
                if line.split()[:1] == [name]:
                    return line
            return None

        def attr_value(text, key):
            idx = text.find(key)
            if idx < 0:
                return None
            rest = text[idx + len(key):].split(',')[0].split()
            return rest[0] if rest else None

        # Baseline: speed and link state before the attempt (needed for the reject branch).
        dut.mode('#')
        base_if = dut.cmd('show interface {}'.format(name))
        base_row = port_row(dut.cmd('show interface {} status'.format(name)))
        base_up = base_row is not None and 'connected' in base_row.split()
        base_cfg_speed = attr_value(base_if, 'configured speed ')
        base_cur_speed = attr_value(base_if, 'current speed ')
        self.log('INFO: baseline {} row: {}; configured speed {}; current speed {}'.format(
            name, base_row, base_cfg_speed, base_cur_speed))

        # Port type per the speed legal-values table: a fixed RJ.5/RJ-45 copper port lists 10.
        # A pluggable copper module's row depends on the module (tri-speed lists 10, 1000 Mbps
        # copper SFP and multi-speed SFP+ do not), so there only the DUT's own response decides.
        plug = dut.cmd('show system pluggable')
        is_pluggable = any(line.split()[:1] == [name] for line in plug.splitlines())
        speed10_legal = None if is_pluggable else True
        self.log('INFO: {} is {}; table lists speed 10: {}'.format(
            name, 'a pluggable copper module' if is_pluggable else 'a fixed RJ-45 copper port',
            'depends on module' if speed10_legal is None else 'yes'))

        # Partner first.
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer_out = peer.cmd('speed 10')
        peer_out += peer.cmd('duplex full')
        peer.mode('#')
        peer_rejected = any(tok in peer_out for tok in err_tokens)
        if peer_rejected:
            self.log('INFO: partner {} rejected speed 10/duplex full on {}: {}; link-up not judged'.format(
                peer, portDut.name, peer_out.strip()))

        # Then the DUT copper test port.
        dut.mode(')#')
        dut.cmd('interface {}'.format(name))
        dut_speed_out = dut.cmd('speed 10')
        dut_duplex_out = dut.cmd('duplex full')
        dut.mode('#')
        dut_rejected = any(tok in dut_speed_out for tok in err_tokens)

        # Poll show interface status for up to 30 s.
        row = None
        deadline = time.time() + 30
        while True:
            row = port_row(dut.cmd('show interface {} status'.format(name), log=False))
            if row is not None and 'connected' in row.split():
                break
            if time.time() >= deadline:
                break
            time.sleep(2)

        if_out = dut.cmd('show interface {}'.format(name))
        rc_out = dut.cmd('show running-config interface {}'.format(name))
        link_running = checkLinkStatus(self, dut, portPeer, 'running')
        self.log('INFO: show interface brief link status running: {}'.format(link_running))

        output = 'speed 10 -> [{}]; duplex full -> [{}]; status row: {}; show interface: {}; running-config: {}'.format(
            dut_speed_out.strip(), dut_duplex_out.strip(), row, if_out, rc_out)
        self.log('OBSERVED: {}'.format(output))

        rc_speed10 = any(line.strip() == 'speed 10' for line in rc_out.splitlines())

        if not dut_rejected:
            self.passed('DUT accepted speed 10 on {} (response: [{}])'.format(name, dut_speed_out.strip()))
            if 'configured duplex full, configured speed 10,' in if_out:
                self.passed('{} show interface reads configured duplex full, configured speed 10'.format(name))
            else:
                self.failed('{} configured duplex {} / configured speed {}, expected full / 10'.format(
                    name, attr_value(if_out, 'configured duplex '), attr_value(if_out, 'configured speed ')))
            if rc_speed10:
                self.passed('running-config for {} contains speed 10'.format(name))
            else:
                self.failed('running-config for {} has no speed 10 line after accepted command: {}'.format(
                    name, rc_out.strip()))
            if peer_rejected:
                self.log('INFO: partner rejected speed 10; status row and current line not judged')
            elif row is None:
                self.failed('port {} missing from show interface status output'.format(name))
            else:
                tokens = row.split()
                pair = any(tokens[i] == 'full' and tokens[i + 1] == '10' for i in range(len(tokens) - 1))
                if 'connected' in tokens and pair and 'a-10' not in tokens and 'a-full' not in tokens:
                    self.passed('{} status row reads connected with bare full and bare 10: {}'.format(name, row))
                else:
                    self.failed('{} status row within 30 s is not connected with bare full/10: {}'.format(
                        name, row))
                if 'current duplex full, current speed 10,' in if_out:
                    self.passed('{} current line reads current duplex full, current speed 10'.format(name))
                else:
                    self.failed('{} current duplex {} / current speed {}, expected full / 10'.format(
                        name, attr_value(if_out, 'current duplex '), attr_value(if_out, 'current speed ')))
        else:
            if speed10_legal:
                self.failed('DUT rejected speed 10 on fixed copper port {} although the table lists 10 for RJ-45 copper: [{}]'.format(
                    name, dut_speed_out.strip()))
            else:
                self.passed('DUT rejected speed 10 on pluggable {} with error indication: [{}]'.format(
                    name, dut_speed_out.strip()))
            if not rc_speed10:
                self.passed('running-config for {} gained no speed 10 line'.format(name))
            else:
                self.failed('running-config for {} contains speed 10 despite rejection: {}'.format(
                    name, rc_out.strip()))
            after_up = row is not None and 'connected' in row.split()
            after_cfg_speed = attr_value(if_out, 'configured speed ')
            after_cur_speed = attr_value(if_out, 'current speed ')
            if after_cfg_speed == base_cfg_speed and after_cur_speed == base_cur_speed and after_up == base_up:
                self.passed('{} speed and link state unchanged: configured speed {}, current speed {}, up {}'.format(
                    name, after_cfg_speed, after_cur_speed, after_up))
            else:
                self.failed('{} changed after rejected speed 10: configured speed {} -> {}, current speed {} -> {}, up {} -> {}'.format(
                    name, base_cfg_speed, after_cfg_speed, base_cur_speed, after_cur_speed, base_up, after_up))

        combined = dut_speed_out + dut_duplex_out + if_out + rc_out
        seen = [tok for tok in boot_tokens if tok in combined]
        if not seen:
            self.passed('DUT console stayed at the prompt with no boot output')
        else:
            self.failed('DUT console showed boot output after speed 10: {}'.format(', '.join(seen)))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        # Reverts main()'s speed 10 / duplex full on both ends to speed/duplex/polarity auto.
        configureDefaultPort(self, dut, portPeer)
        configureDefaultPort(self, peer, portDut)
        dut.mode('#')
        peer.mode('#')


class TestCase_3(ATTestCase.TestCase):
    testCaseDesc = 'On the copper test link, attempt `100` whatever the port type. On the partner port apply `speed 100` and `duplex full`, then on the DUT copper test port apply `speed 100` and `duplex full`. Poll `show interface <copper test port> status` for up to 30 s, then read `show interface <copper test port>` and `show running-config interface <copper test port>`.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33235, 9001.33235.3'
    testCaseMethod = 'On the copper test link, attempt `100` whatever the port type. On the partner port apply `speed 100` and `duplex full`, then on the DUT copper test port apply `speed 100` and `duplex full`. Poll `show interface <copper test port> status` for up to 30 s, then read `show interface <copper test port>` and `show running-config interface <copper test port>`.\n'
    testCaseMethod += "Verify: If the legal-values table lists `100` for the copper port's type, the DUT accepts the command, the test port row reads `connected` with bare `100` and bare `full` (no `a-` prefix), and the current line reads `current duplex full, current speed 100`. If the legal-values table does not list `100` for the port's type, the DUT rejects the command with an error indication, running-config gains no `speed 100` line, and the port's previous speed and link state are unchanged. If the partner rejects the command, log it; judge only the DUT's accept or reject, and do not assert link-up. The console stays at the prompt with no boot output.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Start from the default auto-negotiated state on both ends of the copper test link.
        configureDefaultPort(self, peer, portDut)
        peer.mode('#')
        configureDefaultPort(self, dut, portPeer)
        dut.mode('#')

    def main(self):
        # legacy 5703_Speed_Duplex_Polarity/test-5000.1002.py lines 91-124 (py2→py3)
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        self.log('STEP 4: On the copper test link, attempt `100` whatever the port type. On the partner port apply `speed 100` and `duplex full`, then on the DUT copper test port apply `speed 100` and `duplex full`. Poll `show interface <copper test port> status` for up to 30 s, then read `show interface <copper test port>` and `show running-config interface <copper test port>`.')

        name = portPeer.name

        def status_row(text):
            for line in text.splitlines():
                if line.split()[:1] == [name]:
                    return line
            return None

        def configured_speed(text):
            for line in text.splitlines():
                marker = 'configured speed '
                if marker in line:
                    return line.split(marker, 1)[1].split(',')[0].strip()
            return None

        # The copper test link is the fixed copper port (RJ-45 / RJ.5); the legal-values
        # table lists 100 for both of those port types, so the DUT is expected to accept it.
        expect_supported = True

        # Baseline before the change, used to prove "unchanged" if the DUT rejects.
        dut.mode('#')
        base_status = dut.cmd('show interface {} status'.format(name))
        base_row = status_row(base_status)
        base_up = base_row is not None and 'connected' in base_row.split()
        base_intf = dut.cmd('show interface {}'.format(name))
        base_speed = configured_speed(base_intf)
        self.log('INFO: baseline {} row: {} ; configured speed: {}'.format(name, base_row, base_speed))

        # Partner first, then the DUT.
        peer_speed_ok = configurePort(self, peer, portDut, 'speed', '100', 0)
        peer_duplex_ok = configurePort(self, peer, portDut, 'duplex', 'full', 0)
        peer.mode('#')
        peer_ok = peer_speed_ok and peer_duplex_ok
        if not peer_ok:
            self.log('INFO: partner {} rejected speed 100 / duplex full (speed ok={}, duplex ok={}); link-up is not asserted'.format(
                portDut.name, peer_speed_ok, peer_duplex_ok))

        dut_speed_ok = configurePort(self, dut, portPeer, 'speed', '100', 0)
        dut_duplex_ok = configurePort(self, dut, portPeer, 'duplex', 'full', 0)
        dut.mode('#')

        # Poll the status row for up to 30 s.
        status = ''
        row = None
        deadline = time.time() + 30
        while True:
            status = dut.cmd('show interface {} status'.format(name), log=False)
            row = status_row(status)
            if row is not None and 'connected' in row.split():
                break
            if time.time() >= deadline:
                break
            time.sleep(2)
        checkLinkStatus(self, dut, portPeer, 'running')

        intf = dut.cmd('show interface {}'.format(name))
        runcfg = dut.cmd('show running-config interface {}'.format(name))
        output = '\n'.join([status, intf, runcfg])
        self.log('OBSERVED: {}'.format(output))

        cfg_lines = [line.strip() for line in runcfg.splitlines()]

        if dut_speed_ok == expect_supported:
            self.passed('DUT {} accepted speed 100 as the legal-values table requires for a fixed copper port'.format(name))
        else:
            self.failed('DUT {} rejected speed 100 although the legal-values table lists 100 for RJ-45/RJ.5 copper ports'.format(name))

        if dut_speed_ok:
            if 'speed 100' in cfg_lines:
                self.passed('running-config for {} contains speed 100'.format(name))
            else:
                self.failed('running-config for {} has no speed 100 line after the command was accepted: {}'.format(
                    name, cfg_lines))
            if dut_duplex_ok and 'duplex full' in cfg_lines:
                self.passed('DUT {} accepted duplex full and running-config contains duplex full'.format(name))
            else:
                self.failed('DUT {} duplex full not applied (accepted={}, running-config={})'.format(
                    name, dut_duplex_ok, cfg_lines))

            if peer_ok:
                if row is None:
                    self.failed('port {} missing from show interface status output'.format(name))
                    return
                tokens = row.split()
                if 'connected' in tokens:
                    self.passed('{} status row reads connected: {}'.format(name, row.strip()))
                    idx = tokens.index('connected')
                    duplex_tok = tokens[idx + 2] if len(tokens) > idx + 2 else None
                    speed_tok = tokens[idx + 3] if len(tokens) > idx + 3 else None
                    if duplex_tok == 'full' and speed_tok == '100':
                        self.passed('{} status row shows bare full and bare 100 (no a- prefix)'.format(name))
                    else:
                        self.failed('{} status row shows duplex {} speed {}, expected bare full and 100'.format(
                            name, duplex_tok, speed_tok))
                else:
                    self.failed('{} status row did not reach connected within 30 s: {}'.format(name, row.strip()))
                if 'current duplex full, current speed 100,' in intf:
                    self.passed('{} show interface reads current duplex full, current speed 100'.format(name))
                else:
                    self.failed('{} show interface lacks current duplex full, current speed 100'.format(name))
            else:
                self.log('INFO: partner rejected the command; judging only the DUT accept, link state not asserted')
        else:
            if 'speed 100' not in cfg_lines:
                self.passed('running-config for {} gained no speed 100 line after the rejection'.format(name))
            else:
                self.failed('running-config for {} contains speed 100 although the DUT rejected it'.format(name))
            after_speed = configured_speed(intf)
            if after_speed == base_speed:
                self.passed('{} configured speed unchanged at {}'.format(name, after_speed))
            else:
                self.failed('{} configured speed changed from {} to {} after a rejected command'.format(
                    name, base_speed, after_speed))
            after_up = row is not None and 'connected' in row.split()
            if after_up == base_up:
                self.passed('{} link state unchanged (connected={})'.format(name, after_up))
            else:
                self.failed('{} link state changed from connected={} to connected={}'.format(name, base_up, after_up))

        dut.mode('#')
        if 'Bootloader' not in output and 'login:' not in output:
            self.passed('DUT console stayed at the prompt with no boot output')
        else:
            self.failed('boot output or login prompt seen on the DUT console during the speed change')

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Revert speed 100 / duplex full on both ends to auto.
        configureDefaultPort(self, dut, portPeer)
        dut.mode('#')
        configureDefaultPort(self, peer, portDut)
        peer.mode('#')
        deadline = time.time() + 30
        while time.time() < deadline:
            status = dut.cmd('show interface {} status'.format(portPeer.name), log=False)
            up = False
            for line in status.splitlines():
                if line.split()[:1] == [portPeer.name] and 'connected' in line.split():
                    up = True
                    break
            if up:
                break
            time.sleep(2)
        dut.mode('#')


