    testCaseMethod += "Verify: If the legal-values table lists `2500` for the copper port's type, the DUT accepts the command, the test port row reads `connected` with bare `2500` and bare `full` (no `a-` prefix), and the current line reads `current duplex full, current speed 2500`. If the legal-values table does not list `2500` for the port's type, the DUT rejects the command with an error indication, running-config gains no `speed 2500` line, and the port's previous speed and link state are unchanged. If the partner rejects the command, log it; judge only the DUT's accept or reject, and do not assert link-up. The console stays at the prompt with no boot output.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Per-case PRECONDITIONS: both ends of the copper test link start from the default
        # auto speed / auto duplex / auto polarity, so the baseline main() records is known.
        configureDefaultPort(self, peer, portDut)
        peer.mode('#')
        configureDefaultPort(self, dut, portPeer)
        dut.mode('#')
        time.sleep(5)

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0005-CopperFixed2.5G_5G_Straight.py lines 1919-1995
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        self.log('STEP 6: On the copper test link, attempt `2500` whatever the port type. On the partner port apply `speed 2500` and `duplex full`, then on the DUT copper test port apply `speed 2500` and `duplex full`. Poll `show interface <copper test port> status` for up to 30 s, then read `show interface <copper test port>` and `show running-config interface <copper test port>`.')
        name = portPeer.name

        def if_field(text, key):
            # 'show interface' prints comma-separated attributes, e.g.
            # 'configured duplex auto, configured speed auto, configured polarity auto'
            for line in text.splitlines():
                for part in line.split(','):
                    part = part.strip()
                    if part.startswith(key + ' '):
                        return part[len(key) + 1:].strip()
            return None

        def status_row():
            out = dut.cmd('show interface {} status'.format(name))
            row = next((line for line in out.splitlines() if line.split()[:1] == [name]), None)
            return out, row

        # Baseline of the DUT copper test port before the speed change
        dut.mode('#')
        base_if = dut.cmd('show interface {}'.format(name))
        base_conf_speed = if_field(base_if, 'configured speed')
        base_cur_speed = if_field(base_if, 'current speed')
        base_running = checkLinkStatus(self, dut, portPeer, 'running')
        base_status_out, base_row = status_row()
        self.log('BASELINE {}: configured speed {}, current speed {}, running {}, status row: {}'.format(
            name, base_conf_speed, base_cur_speed, base_running, base_row))

        # Partner first: speed 2500 then duplex full (judged only by logging)
        p_speed_ok = configurePort(self, peer, portDut, 'speed', '2500', 0)
        p_duplex_ok = configurePort(self, peer, portDut, 'duplex', 'full', 0)
        peer.mode('#')
        partner_ok = p_speed_ok and p_duplex_ok
        if not p_speed_ok:
            self.log('INFO: partner {} rejected speed 2500 on {}; link-up is not asserted'.format(peer, portDut.name))
        if not p_duplex_ok:
            self.log('INFO: partner {} rejected duplex full on {}; link-up is not asserted'.format(peer, portDut.name))

        # DUT: speed 2500 then duplex full; configurePort returns False when the CLI printed
        # an error indication ('failed' / 'Cannot' / 'Invalid')
        d_speed_ok = configurePort(self, dut, portPeer, 'speed', '2500', 0)
        d_duplex_ok = configurePort(self, dut, portPeer, 'duplex', 'full', 0)
        dut.mode('#')

        # Poll the status row for up to 30 s
        status_out, row = status_row()
        deadline = time.time() + 30
        while (row is None or 'connected' not in row.split()) and time.time() < deadline:
            time.sleep(2)
            status_out, row = status_row()

        if_out = dut.cmd('show interface {}'.format(name))
        rc_out = dut.cmd('show running-config interface {}'.format(name))
        after_running = checkLinkStatus(self, dut, portPeer, 'running')
        after_conf_speed = if_field(if_out, 'configured speed')
        rc_has_2500 = any(line.strip() == 'speed 2500' for line in rc_out.splitlines())

        output = '\n'.join([status_out, if_out, rc_out])
        self.log('OBSERVED: {}'.format(output))

        # Console must stay at the prompt with no boot output
        boot_markers = ['Bootloader', 'Restarting system', 'Linux version', 'Loading']
        seen_boot = [marker for marker in boot_markers if marker in output]
        if seen_boot:
            self.failed('Boot output seen on DUT console after speed 2500: {}'.format(seen_boot))
            return
        else:
            self.passed('DUT console stayed at the prompt, no boot output seen')

        # A port that previously ran above 1000 Mbps is a multi-speed RJ-45 port, whose
        # legal-values row lists 2500 — a rejection there is a defect.
        multigig = base_cur_speed is not None and base_cur_speed.isdigit() and int(base_cur_speed) > 1000

        if d_speed_ok:
            self.passed('DUT accepted speed 2500 on {} with no error indication'.format(name))
            if d_duplex_ok:
                self.passed('DUT accepted duplex full on {} with no error indication'.format(name))
            else:
                self.failed('DUT rejected duplex full on {} although speed 2500 was accepted'.format(name))
            if rc_has_2500:
                self.passed('running-config for {} contains speed 2500'.format(name))
            else:
                self.failed('running-config for {} has no speed 2500 line after it was accepted'.format(name))
            if after_conf_speed == '2500':
                self.passed('{} configured speed is 2500'.format(name))
            else:
                self.failed('{} configured speed is {}, expected 2500'.format(name, after_conf_speed))
            if not partner_ok:
                self.log('INFO: partner rejected the 2500/full settings; link-up and current speed not asserted')
                return
            if row is None:
                self.failed('port {} missing from show interface status output'.format(name))
                return
            tokens = row.split()
            if 'connected' in tokens:
                self.passed('{} status row reads connected: {}'.format(name, row))
            else:
                self.failed('{} status row not connected within 30 s: {}'.format(name, row))
            if '2500' in tokens and 'a-2500' not in tokens:
                self.passed('{} status row shows bare 2500 speed'.format(name))
            else:
                self.failed('{} status row does not show bare 2500 speed: {}'.format(name, row))
            if 'full' in tokens and 'a-full' not in tokens:
                self.passed('{} status row shows bare full duplex'.format(name))
            else:
                self.failed('{} status row does not show bare full duplex: {}'.format(name, row))
            if 'current duplex full, current speed 2500' in if_out:
                self.passed('{} reports current duplex full, current speed 2500'.format(name))
            else:
                self.failed('{} current line is duplex {}, speed {}; expected full / 2500'.format(
                    name, if_field(if_out, 'current duplex'), if_field(if_out, 'current speed')))
        else:
            if multigig:
                self.failed('DUT rejected speed 2500 on {} although it previously ran at {} Mbps (multi-speed port lists 2500)'.format(name, base_cur_speed))
            else:
                self.passed('DUT rejected speed 2500 on {} with an error indication (2500 not legal for this port type)'.format(name))
            if not rc_has_2500:
                self.passed('running-config for {} gained no speed 2500 line'.format(name))
            else:
                self.failed('running-config for {} contains speed 2500 although the command was rejected'.format(name))
            if after_conf_speed == base_conf_speed:
                self.passed('{} configured speed unchanged at {}'.format(name, after_conf_speed))
            else:
                self.failed('{} configured speed changed from {} to {} after a rejected speed 2500'.format(
                    name, base_conf_speed, after_conf_speed))
            if partner_ok:
                self.log('INFO: partner accepted speed 2500 while the DUT rejected it; a link change is attributable to the partner, link state not judged')
            elif after_running == base_running:
                self.passed('{} link state unchanged (running={})'.format(name, after_running))
            else:
                self.failed('{} link state changed from running={} to running={} after a rejected speed 2500'.format(
                    name, base_running, after_running))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Undo main()'s speed 2500 / duplex full on both ends: back to speed auto / duplex auto.
        configureDefaultPort(self, dut, portPeer)
        dut.mode('#')
        configureDefaultPort(self, peer, portDut)
        peer.mode('#')
        time.sleep(5)


