        bootMarkers = ('login:', 'Bootloader', 'Restarting', 'Loading')
        dutOutputs = []

        def is_error(text):
            return any(marker in text for marker in errorMarkers)

        def error_line(text):
            return next((line.strip() for line in text.splitlines() if is_error(line)), text.strip())

        def field(text, key):
            for part in text.replace('\n', ',').split(','):
                part = part.strip()
                if part.startswith(key + ' '):
                    return part[len(key):].strip()
            return None

        def status_row():
            out = dut.cmd('show interface {} status'.format(name), log=False)
            dutOutputs.append(out)
            return next((line for line in out.splitlines() if line.split()[:1] == [name]), None)

        def row_up(row):
            return row is not None and 'connected' in row.split()

        # Baseline: let the default-configured link settle, then record speed and link state.
        dut.mode('#')
