        peerDuplexOut = fibre_peer.cmd('duplex full')
        fibre_peer.mode('#')
        partnerRejected = is_error(peerSpeedOut)
        if partnerRejected:
            self.log('INFO: partner {} rejected speed 10000: {}'.format(farPort.name, error_line(peerSpeedOut)))
        if is_error(peerDuplexOut):
            self.log('INFO: partner {} rejected duplex full: {}'.format(farPort.name, error_line(peerDuplexOut)))

        # Then the DUT fibre test port.
