class TestCase_15(ATTestCase.TestCase):
    testCaseDesc = 'Read `show interface <test port>` and `show interface <test port> status` with fixed speed S in effect.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33235, 9001.33235.15'
    testCaseMethod = 'Read `show interface <test port>` and `show interface <test port> status` with fixed speed S in effect.\n'
    testCaseMethod += 'Verify: The configured speed line in `show interface` reports S. The current line reads `current speed S`. The status row speed column reads bare S. All three agree with the value applied in step 14.\n'

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Re-establish the step 14 state this step presumes: fixed speed S on the fixed
        # copper test port (dut.portPeer) and on its partner (peer.portDut), partner first.
        fixed_speed = '1000'
        self.speedRejected = False
        if not configurePort(self, peer, portDut, 'speed', fixed_speed, 0):
            self.log('INFO: partner {} rejected speed {} on {}'.format(peer, fixed_speed, portDut.name))
        if not configurePort(self, dut, portPeer, 'speed', fixed_speed, 0):
            self.log('INFO: DUT {} rejected speed {} on {}'.format(dut, fixed_speed, portPeer.name))
            self.speedRejected = True
        peer.mode('#')
        dut.mode('#')

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 122-204
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        self.log('STEP 16: Read `show interface <test port>` and `show interface <test port> status` with fixed speed S in effect.')
        fixed_speed = '1000'
        name = portPeer.name

        if getattr(self, 'speedRejected', False):
            self.supported = False
            self.log('INFO: {} does not accept fixed speed {} on {}; case not applicable'.format(
                dut, fixed_speed, name))
            return

        def value_after(text, key):
            idx = text.find(key)
            if idx < 0:
                return None
            rest = text[idx + len(key):]
            return rest.split('\n')[0].split(',')[0].strip()

        dut.mode('#')
        output = ''
        deadline = time.time() + 30
        while True:
            output = dut.cmd('show interface {}'.format(name), log=False)
            if 'Link is UP' in output and value_after(output, 'current speed ') == fixed_speed:
                break
            if time.time() > deadline:
                break
            time.sleep(2)
        status_out = dut.cmd('show interface {} status'.format(name))
        self.log('OBSERVED: {}'.format(output))
        self.log('OBSERVED: {}'.format(status_out))

        configured = value_after(output, 'configured speed ')
        if configured == fixed_speed:
            self.passed('{} show interface reports configured speed {}'.format(name, configured))
        else:
            self.failed('{} show interface reports configured speed {}, expected {}'.format(
                name, configured, fixed_speed))

        if 'Link is UP' not in output:
            self.failed('{} link is not UP within 30 s with fixed speed {}; no current speed to read'.format(
                name, fixed_speed))
            return

        current = value_after(output, 'current speed ')
        if current == fixed_speed:
            self.passed('{} show interface reads current speed {}'.format(name, current))
        else:
            self.failed('{} show interface reads current speed {}, expected {}'.format(
                name, current, fixed_speed))

        row = next((line for line in status_out.splitlines() if line.split()[:1] == [name]), None)
        if row is None:
            self.failed('port {} missing from show interface status output'.format(name))
            return
        tokens = row.split()
        status_speed = None
        if fixed_speed in tokens:
            status_speed = fixed_speed
        else:
            status_speed = next((tok for tok in tokens if tok.endswith(fixed_speed)), None)
        if status_speed == fixed_speed and 'a-{}'.format(fixed_speed) not in tokens:
            self.passed('{} status row speed column reads bare {}: {}'.format(name, status_speed, row.strip()))
        else:
            self.failed('{} status row speed column is not bare {} (found {}): {}'.format(
                name, fixed_speed, status_speed, row.strip()))

        if configured == fixed_speed and current == fixed_speed and status_speed == fixed_speed:
            self.passed('{} configured speed {}, current speed {} and status speed {} all agree with applied speed {}'.format(
                name, configured, current, status_speed, fixed_speed))
        else:
            self.failed('{} speeds disagree with applied {}: configured {}, current {}, status {}'.format(
                name, fixed_speed, configured, current, status_speed))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Mirror configure(): return both ends of the copper link to the default speed.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.mode('#')
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.mode('#')


