class TestCase_20(ATTestCase.TestCase):
    testCaseDesc = "Run this only where both 10 and 100 are legal for the test port's type (copper). On single-speed media an incompatible fixed pair cannot be built, so skip and log it as not applicable. Force BOTH ends: on the DUT test port apply `speed 100` and `duplex full`; on the partner port apply `speed 10` and `duplex full`. Every 5 s for 60 s, read `show interface <test port> status`, `show interface <test port>` and the partner's status row. Then read `show log`."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33235, 9001.33235.20'
    testCaseMethod = "Run this only where both 10 and 100 are legal for the test port's type (copper). On single-speed media an incompatible fixed pair cannot be built, so skip and log it as not applicable. Force BOTH ends: on the DUT test port apply `speed 100` and `duplex full`; on the partner port apply `speed 10` and `duplex full`. Every 5 s for 60 s, read `show interface <test port> status`, `show interface <test port>` and the partner's status row. Then read `show log`.\n"
    testCaseMethod += 'Verify: Throughout the whole 60 s window, the test port row never contains `connected` and neither does the partner row. `show interface <test port>` has no `current speed` value. The log contains no link-up event for the test port during the window.\n'

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # Start both ends of the copper link from default speed/duplex so the forced
        # mismatch applied in main() is the only thing in effect.
        for dev, port in ((dut, portPeer), (peer, portDut)):
            dev.mode(')#')
            dev.cmd('interface {}'.format(port.name))
            dev.cmd('no speed')
            dev.cmd('duplex auto')
            dev.mode('#')

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 61-85
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        self.log("STEP 21: Run this only where both 10 and 100 are legal for the test port's type (copper). On single-speed media an incompatible fixed pair cannot be built, so skip and log it as not applicable. Force BOTH ends: on the DUT test port apply `speed 100` and `duplex full`; on the partner port apply `speed 10` and `duplex full`. Every 5 s for 60 s, read `show interface <test port> status`, `show interface <test port>` and the partner's status row. Then read `show log`.")
        testName = portPeer.name
        partnerName = portDut.name

        # Log baseline, so only entries written during this step are judged later.
        dut.mode('#')
        logBefore = dut.cmd('show log tail 250')
        baseline = set(logBefore.splitlines())

        # Capability probe: speed 10 on the partner and speed 100 on the DUT must both be
        # accepted; a rejection means single-speed media where the mismatch cannot be built.
        if not configurePort(self, peer, portDut, 'speed', '10', 0):
            self.supported = False
            self.log('INFO: {} {} rejected speed 10 (single-speed media); incompatible fixed pair cannot be built, case not applicable'.format(peer, partnerName))
            return
        if not configurePort(self, dut, portPeer, 'speed', '100', 0):
            self.supported = False
            self.log('INFO: {} {} rejected speed 100 (single-speed media); incompatible fixed pair cannot be built, case not applicable'.format(dut, testName))
            return
        partnerDuplexOk = configurePort(self, peer, portDut, 'duplex', 'full', 0)
        dutDuplexOk = configurePort(self, dut, portPeer, 'duplex', 'full', 0)
        if not (partnerDuplexOk and dutDuplexOk):
            self.failed('duplex full was rejected (partner {} accepted={}, DUT {} accepted={}); forced mismatch not established'.format(
                partnerName, partnerDuplexOk, testName, dutDuplexOk))
            return

        dut.mode('#')
        cfgOut = dut.cmd('show interface {}'.format(testName))
        if 'configured speed 100,' in cfgOut and 'configured duplex full' in cfgOut:
            self.passed('{} shows configured speed 100 and configured duplex full'.format(testName))
        else:
            self.failed('{} does not show configured speed 100 / configured duplex full after forcing'.format(testName))

        # 60 s observation window, sampled every 5 s.
        dutConnected = []
        partnerConnected = []
        dutRowMissing = []
        partnerRowMissing = []
        currentSpeeds = []
        samples = []
        for sample in range(13):
            elapsed = sample * 5
            dut.mode('#')
            dutStatus = dut.cmd('show interface {} status'.format(testName), log=False)
            dutIntf = dut.cmd('show interface {}'.format(testName), log=False)
            peer.mode('#')
            peerStatus = peer.cmd('show interface {} status'.format(partnerName), log=False)

            dutRow = next((line for line in dutStatus.splitlines()
                           if line.split()[:1] == [testName]), None)
            peerRow = next((line for line in peerStatus.splitlines()
                            if line.split()[:1] == [partnerName]), None)
            if dutRow is None:
                dutRowMissing.append(elapsed)
            elif 'connected' in dutRow.split():
                dutConnected.append(elapsed)
            if peerRow is None:
                partnerRowMissing.append(elapsed)
            elif 'connected' in peerRow.split():
                partnerConnected.append(elapsed)
            speedMatch = re.search(r'current speed (\d+)', dutIntf)
            if speedMatch:
                currentSpeeds.append((elapsed, speedMatch.group(1)))
            samples.append('t={}s DUT[{}] partner[{}] current speed={}'.format(
                elapsed, dutRow, peerRow, speedMatch.group(1) if speedMatch else 'none'))
            if sample < 12:
                time.sleep(5)

        dut.mode('#')
        lastIntf = dut.cmd('show interface {}'.format(testName))
        logAfter = dut.cmd('show log tail 250')
        newLines = [line for line in logAfter.splitlines() if line not in baseline]
        linkUpLines = []
        for line in newLines:
            tokens = [tok.strip(',.:;()[]') for tok in line.split()]
            if testName in tokens and ('up' in tokens or 'UP' in tokens):
                linkUpLines.append(line)

        output = '\n'.join(samples) + '\nshow interface {} (end of window):\n{}\nnew log entries:\n{}'.format(
            testName, lastIntf, '\n'.join(newLines))
        self.log('OBSERVED: {}'.format(output))

        if dutRowMissing:
            self.failed('{} row missing from show interface status at t={} s'.format(testName, dutRowMissing))
        elif dutConnected:
            self.failed('{} row read connected at t={} s despite forced speed 100 vs partner speed 10'.format(
                testName, dutConnected))
        else:
            self.passed('{} row never read connected in any of the 13 samples over 60 s'.format(testName))

        if partnerRowMissing:
            self.failed('partner {} row missing from show interface status at t={} s'.format(
                partnerName, partnerRowMissing))
        elif partnerConnected:
            self.failed('partner {} row read connected at t={} s despite forced speed 10 vs DUT speed 100'.format(
                partnerName, partnerConnected))
        else:
            self.passed('partner {} row never read connected in any of the 13 samples over 60 s'.format(partnerName))

        if currentSpeeds:
            self.failed('show interface {} reported a current speed during the window: {}'.format(
                testName, currentSpeeds))
        else:
            self.passed('show interface {} reported no current speed value in any sample'.format(testName))

        if linkUpLines:
            self.failed('show log recorded link-up event(s) for {} during the window: {}'.format(
                testName, linkUpLines))
        else:
            self.passed('show log has no link-up event for {} among {} new entries written during the window'.format(
                testName, len(newLines)))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        for dev, port in ((dut, portPeer), (peer, portDut)):
            dev.mode(')#')
            dev.cmd('interface {}'.format(port.name))
            dev.cmd('no speed')
            dev.cmd('duplex auto')
            dev.mode('#')
        # Give the link time to renegotiate before the next case starts.
        for attempt in range(6):
            if checkLinkStatus(self, dut, portPeer, 'running'):
                break
            time.sleep(5)
        dut.mode('#')
        peer.mode('#')


