class TestCase_25(ATTestCase.TestCase):
    testCaseDesc = 'On the partner port apply `no speed` and `duplex auto` so it auto-negotiates. On the DUT test port apply `no speed` and `duplex auto`. Poll status for up to 30 s, then read `show interface <test port>` and `show running-config interface <test port>`.'
