    testCaseMethod += 'Verify: The test port row reads `connected` with `a-` prefixed speed and duplex, so auto-negotiation is enabled again. The current line shows a concrete speed and duplex equal to the step-2 baseline, not the literal `auto`. Running-config has no numeric `speed` line for the test port.\n'

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        cusfp_peer = self.testSet.cusfp_peer          # None when self.testSet.cusfp_supported is False
        portCuSfp = dut.portCuSfp

        self.baselineDuplex = 'full'
        self.baselineSpeed = '1000'

        if not self.testSet.cusfp_supported or cusfp_peer is None or portCuSfp is None:
            return

        # Precondition this step presumes: the copper-SFP test port was previously forced
        # to a concrete (non-auto) speed/duplex pair by an earlier fixed-speed step, so
        # this step's `no speed` / `duplex auto` action has something real to revert.
        # Capture the auto-negotiated baseline first (the "step-2 baseline" the verify
        # text compares against), then force that same concrete pair explicitly.
        dut.mode('#')
        output = dut.cmd('show interface {}'.format(portCuSfp.name))
        for line in output.splitlines():
            line = line.strip()
            if line.startswith('current duplex'):
                tokens = line.replace(',', '').split()
                self.baselineDuplex = tokens[2]
                self.baselineSpeed = tokens[5]
                break

        cusfp_peer.mode(')#')
        cusfp_peer.cmd('interface {}'.format(cusfp_peer.portCuSfp.name))
        cusfp_peer.cmd('speed {}'.format(self.baselineSpeed))
        cusfp_peer.cmd('duplex {}'.format(self.baselineDuplex))
        cusfp_peer.mode('#')

        dut.mode(')#')
        dut.cmd('interface {}'.format(portCuSfp.name))
        dut.cmd('speed {}'.format(self.baselineSpeed))
        dut.cmd('duplex {}'.format(self.baselineDuplex))
        dut.mode('#')
