        portCuSfp = dut.portCuSfp
        # Precondition this step presumes: the fixed copper test port and its X-over
        # partner are forced to a known, concrete speed/duplex — the "step-2 baseline"
        # main() reverts from and checks the negotiated speed against after going back
        # to auto. Established here (never assumed left over from another case).
        self.baselineSpeed = '1000'
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('speed {}'.format(self.baselineSpeed))
        peer.cmd('duplex full')
        peer.mode('#')
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('speed {}'.format(self.baselineSpeed))
        dut.cmd('duplex full')
        dut.mode('#')
